import{_ as a,c as r,o as i,ag as t}from"./chunks/framework.C86mscM5.js";const S=JSON.parse('{"title":"CSR (Client Side Rendering)","description":"","frontmatter":{},"headers":[],"relativePath":"advance/rendering-mode/csr.md","filePath":"advance/rendering-mode/csr.md","lastUpdated":1788689791000}'),n={name:"advance/rendering-mode/csr.md"};function l(o,e,d,c,s,h){return i(),r("div",null,e[0]||(e[0]=[t('<h1 id="csr-client-side-rendering" tabindex="-1">CSR (Client Side Rendering) <a class="header-anchor" href="#csr-client-side-rendering" aria-label="Permalink to &quot;CSR (Client Side Rendering)&quot;">​</a></h1><blockquote><p>CSR 是 &quot;Client-Side Rendering&quot;（客户端渲染）的缩写。它表示页面是在浏览器中通过 JavaScript 渲染的，数据获取、模板和路由等逻辑都在浏览器端完成，而不是在服务器上。</p><p>在 CSR 中，服务器会向浏览器端发送一个空的 HTML 外壳和一些 JavaScript 脚本，然后由浏览器端从服务器的 API 中拉取数据，并将动态内容渲染到页面中。</p></blockquote><h2 id="csr-加载流程" tabindex="-1">CSR 加载流程 <a class="header-anchor" href="#csr-加载流程" aria-label="Permalink to &quot;CSR 加载流程&quot;">​</a></h2><ol><li>浏览器加载 HTML → 用户看到空白页面</li><li>JavaScript 加载完成 → React 渲染页面内容</li><li>后续页面导航 → SPA 模式，客户端渲染</li></ol><h2 id="优点" tabindex="-1">优点 <a class="header-anchor" href="#优点" aria-label="Permalink to &quot;优点&quot;">​</a></h2><ul><li><strong>快速响应</strong>：在初次加载后，页面的交互和导航速度较快，因为不需要每次都向服务器请求完整的 HTML 页面。</li></ul><h2 id="缺点" tabindex="-1">缺点 <a class="header-anchor" href="#缺点" aria-label="Permalink to &quot;缺点&quot;">​</a></h2><ul><li><strong>首屏加载慢</strong>：由于需要等待 JavaScript 加载和执行，首屏渲染可能会比较慢，尤其是在网络状况不佳的情况下。</li><li><strong>SEO 不友好</strong>：搜索引擎爬虫可能无法正确抓取和索引通过 JavaScript 渲染的内容，影响网站的搜索排名。</li></ul><h2 id="如何提升首屏性能" tabindex="-1">如何提升首屏性能 <a class="header-anchor" href="#如何提升首屏性能" aria-label="Permalink to &quot;如何提升首屏性能&quot;">​</a></h2><ul><li>code splitting：将 JavaScript 拆分成多个小文件，按需加载，减少首屏加载的 JS 体积。</li><li>lazy loading：延迟加载非首屏内容，减少首屏渲染的阻塞。</li></ul>',10)]))}const p=a(n,[["render",l]]);export{S as __pageData,p as default};
